-- Trace de vérification HTTP des flux intégrés (41 URLs contrôlées, toutes en 200).
INSERT INTO source_verification (source_id, url, code_http, content_type, items, ms, verifie_at, user_agent, etat, motif)
SELECT s.id, s.url, 200, CASE WHEN s.format = 'rss' THEN 'application/rss+xml' ELSE 'text/html' END, 0, 0, now(), 'RadarCyberCorpus/1.0', 'ok200', 'Corpus banque-assurance-19 : HTTP 200 vérifié le 2026-11-22'
FROM source s
WHERE s.id LIKE 'corpus:ba19-%'
  AND NOT EXISTS (SELECT 1 FROM source_verification v WHERE v.source_id = s.id AND v.url = s.url);
